def choose_move(observation):
    w, h = observation['grid_width'], observation['grid_height']
    (x, y) = observation['self_position']
    opp_x, opp_y = observation['opponent_position']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    remaining = observation.get('remaining_resource_count', 0)
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    def move_towards(target):
        dx = dy = 0
        if target[0] > x: dx = 1
        elif target[0] < x: dx = -1
        if target[1] > y: dy = 1
        elif target[1] < y: dy = -1
        if (x+dx, y+dy) in obstacles or not (0 <= x+dx < w and 0 <= y+dy < h):
            dx = dy = 0
            if target[0] != x:
                step_x = 1 if target[0] > x else -1
                if (x+step_x, y) not in obstacles and 0 <= x+step_x < w:
                    dx = step_x
            if dx == 0 and target[1] != y:
                step_y = 1 if target[1] > y else -1
                if (x, y+step_y) not in obstacles and 0 <= y+step_y < h:
                    dy = step_y
        return [dx, dy]
    if resources:
        target_res = min(resources, key=lambda r: dist((x,y), r))
        return move_towards(target_res)
    else:
        if remaining < 5:
            # move away from opponent to conserve
            if dist((x,y), (opp_x,opp_y)) < 3:
                # move opposite to opponent
                dx = x - opp_x
                dy = y - opp_y
                nx = x + (1 if dx <=0 else -1)
                ny = y + (1 if dy <=0 else -1)
                if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles:
                    return [nx - x, ny - y]
        # move towards opponent if far away
        return move_towards((opp_x, opp_y))
    # default stay in place if no move found
    return [0,0]
